TEST(CeltFrame, MatchesReference) {
    for (const Sequence& seq : kSequences) {
        player::audio::opus::CeltFrameDecoder decoder;
        decoder.init(seq.channels);
        std::vector<float> pcm(seq.frames[0].pcm.size());
        for (const FrameCase& frame : seq.frames) {
            player::audio::opus::RangeDecoder rd(frame.packet.data(),
                                                frame.packet.size());
            std::fill(pcm.begin(), pcm.end(), 0.0f);
            decoder.decode(rd, seq.lm, seq.channels, pcm.data());
            for (int i = 0; i < static_cast<int>(pcm.size()); ++i) {
                EXPECT_NEAR(pcm[i], frame.pcm[i], 1e-6f) << "sample " << i;
            }
        }
    }
}

TEST(OpusDecoder, DecodesCeltPackets) {
    for (const Sequence& seq : kSequences) {
        const uint8_t head[] = {0x4F, 0x70, 0x75, 0x73, 0x48, 0x65, 0x61, 0x64, 0x01,
                                static_cast<uint8_t>(seq.channels), 0x38, 0x01, 0x80,
                                0xBB, 0x00, 0x00, 0x00, 0x00, 0x00};
        player::audio::opus::Decoder decoder;
        std::string error;
        ASSERT_TRUE(decoder.configure(head, sizeof(head), error)) << error;
        player::audio::PcmBuffer pcm;
        int64_t expected_pts = 0;
        for (const FrameCase& frame : seq.frames) {
            std::vector<uint8_t> packet;
            packet.push_back(static_cast<uint8_t>(seq.toc));
            packet.insert(packet.end(), frame.packet.begin(), frame.packet.end());
            ASSERT_EQ(decoder.decode(packet.data(), packet.size(), pcm, error),
                      player::audio::opus::Status::Ok) << error;
            ASSERT_EQ(pcm.samples.size(), frame.pcm.size());
            for (int i = 0; i < static_cast<int>(pcm.samples.size()); ++i) {
                EXPECT_NEAR(pcm.samples[i], frame.pcm[i], 1e-6f) << "sample " << i;
            }
            EXPECT_EQ(pcm.pts, expected_pts);
            EXPECT_EQ(pcm.channels, static_cast<uint32_t>(seq.channels));
            expected_pts += seq.frame_samples;
        }
    }
}
